INSERT INTO `talent_pool` (`id`, `name`, `avatar`, `title`, `region`, `expertise_areas`, `skills`, `experience_years`, `education`, `intro`, `project_experience`, `achievements`, `status`, `sort_order`) VALUES
(1, '张伟', 'https://cube.elemecdn.com/3/7c/3ea6beec64369c2642b92c6726f1epng.png', '高级配方研发工程师', '上海市浦东新区', '["化妆品研发", "天然植物配方", "抗衰老产品"]', '["配方设计", "功效评测", "原料评估", "质量控制"]', 8, '博士', '8年化妆品研发经验，专注于天然植物配方开发，对抗衰老产品有深入研究。曾主导多个知名品牌的产品研发项目。', '[{"name": "某品牌抗衰老系列产品开发", "description": "负责抗衰老系列产品配方研发，成功上市3个系列", "result": "年销售额突破5000万"}, {"name": "天然植物护肤系列", "description": "采用中药植物提取技术，开发温和护肤产品线", "result": "获得国家发明专利"}]', '["发明专利3项", "核心期刊论文2篇", "上海市科技进步奖"]', 1, 100),
(2, '李娜', 'https://cube.elemecdn.com/3/7c/3ea6beec64369c2642b92c6726f1epng.png', '食品研发总监', '广州市天河区', '["功能性食品", "保健品研发", "营养配方"]', '["产品配方", "工艺设计", "临床试验", "申报注册"]', 12, '硕士', '12年食品研发经验，专注功能性食品和保健品研发。具备丰富的新产品从研发到上市的全流程经验。', '[{"name": "胶原蛋白口服液开发", "description": "研发胶原蛋白肽口服液产品", "result": "月销量突破10万瓶"}, {"name": "益生菌固体饮料", "description": "开发适合国人体质的益生菌产品", "result": "成为爆款产品"}]', '["发明专利5项", "SCI论文3篇", "行业专家顾问"]', 1, 90),
(3, '王强', 'https://cube.elemecdn.com/3/7c/3ea6beec64369c2642b92c6726f1epng.png', '原料研发专家', '杭州市西湖区', '["天然原料提取", "功效原料开发", "原料质量标准"]', '["提取工艺", "质量分析", "标准制定", "供应商管理"]', 6, '本科', '6年天然原料提取研发经验，精通各类植物提取工艺，为化妆品和食品行业提供高品质原料支持。', '[{"name": "珍稀植物提取物研发", "description": "研发高山植物活性成分提取技术", "result": "填补国内技术空白"}, {"name": "原料质量标准制定", "description": "建立原料内控质量标准体系", "result": "全面提升原料品质"}]', '["发明专利2项", "参与制定行业标准1项"]', 1, 80),
(4, '陈静', 'https://cube.elemecdn.com/3/7c/3ea6beec64369c2642b92c6726f1epng.png', '配方研究员', '北京市朝阳区', '["护肤配方", "彩妆配方", "产品稳定性研究"]', '["配方开发", "功效验证", "稳定性测试", "安全性评估"]', 4, '硕士', '4年化妆品配方研发经验，擅长护肤和彩妆产品配方开发，对产品稳定性和安全性评估有丰富经验。', '[{"name": "敏感肌护肤系列开发", "description": "开发适合敏感肌的温和护肤产品", "result": "市占率同类产品前三"}, {"name": "长效保湿霜配方优化", "description": "提升产品保湿效果和肤感", "result": "获得用户好评"}]', '["发明专利1项", "发表论文1篇"]', 1, 70),
(5, '刘洋', 'https://cube.elemecdn.com/3/7c/3ea6beec64369c2642b92c6726f1epng.png', '研发项目经理', '深圳市南山区', '["项目管理", "研发规划", "团队管理"]', '["项目策划", "进度管控", "资源协调", "跨部门协作"]', 10, '硕士', '10年研发管理经验，擅长研发项目全生命周期管理曾管理多个大型研发项目，准时交付率100%。', '[{"name": "研发平台建设项目", "description": "搭建公司级研发技术平台", "result": "提升研发效率30%"}, {"name": "研发团队扩建项目", "description": "从10人团队扩展到50人规模", "result": "支撑公司业务快速增长"}]', '["PMP认证", "优秀管理者奖", "发表管理论文2篇"]', 1, 60),
(6, '赵敏', 'https://cube.elemecdn.com/3/7c/3ea6beec64369c2642b92c6726f1epng.png', '功效评价工程师', '成都市武侯区', '["功效评测", "临床研究", "消费者调研"]', '["体外评测", "人体试验", "数据分析", "报告撰写"]', 5, '本科', '5年功效评价经验，精通化妆品功效评测方法建立和实施，为产品功效宣称提供科学依据。', '[{"name": "抗蓝光功效评价体系建立", "description": "建立全面的抗蓝光产品功效评价方法", "result": "行业领先标准"}, {"name": "多肽原料功效研究", "description": "系统评估多肽原料的功效表现", "result": "指导产品配方优化"}]', '["功效评测师资质", "行业标准参与制定1项"]', 1, 50),
(7, '孙磊', 'https://cube.elemecdn.com/3/7c/3ea6beec64369c2642b92c6726f1epng.png', '包装研发工程师', '南京市鼓楼区', '["包装材料", "包装设计", "包材相容性"]', '["材料选型", "结构设计", "相容性测试", "成本优化"]', 7, '本科', '7年包装研发经验，精通各类化妆品和食品包装材料的研发与应用，注重包装创新与成本控制。', '[{"name": "环保包装材料研发", "description": "开发生物可降解包装材料", "result": "减少包材碳排放40%"}, {"name": "包装防伪系统升级", "description": "升级产品防伪包装方案", "result": "有效遏制假冒产品"}]', '["包装设计师资质", "实用新型专利2项"]', 1, 40),
(8, '周婷', 'https://cube.elemecdn.com/3/7c/3ea6beec64369c2642b92c6726f1epng.png', '品质控制经理', '武汉市洪山区', '["质量管理体系", "检测方法开发", "供应商质量管理"]', '["质量体系建设", "检测技术", "偏差处理", "审计整改"]', 9, '本科', '9年品质控制经验，建立了完善的质量管理体系，精通各类检测方法的开发和验证。', '[{"name": "CNAS实验室建设", "description": "主导实验室CNAS认可工作", "result": "一次性通过评审"}, {"name": "全面质量管理体系升级", "description": "重构公司质量管理体系", "result": "质量投诉下降60%"}]', '["CNAS评审员资质", "质量工程师高级证书"]', 1, 30);
